import React from "react";
import { AbsoluteFill, useCurrentFrame } from "remotion";
import { Camera, ParallaxLayer, useCamera } from "../camera/Camera";
import { Stage } from "../stage/Stage";
import { SceneLighting } from "../stage/SceneLighting";
import { PaperBackground } from "../paper/PaperBackground";
import { GoldFrame } from "../ornaments/GoldFrame";
import { SkyGradient, SunOnWire, wirePoint } from "../sets/Sky";
import {
  ArchNiche,
  HangingPlanet,
  HangingStar,
  StringLights,
} from "../sets/CelebrationSets";
import { Character } from "../characters/Character";
import { people, wardrobe } from "../characters/cast";
import { Flower, GarlandSwag, Leaf } from "../props/Florals";
import { PetalScatter } from "../props/CelebrationProps";
import { Diya } from "../props/Ganesh";
import { EventTitle } from "../kit/EventTitle";
import { FallingPetals, GoldDust } from "../kit/Particles";
import { EASE, mix, prog, wave } from "../kit/motion";
import { palette } from "../theme/palette";
import type { SceneProps } from "./types";
import { bi, whenBi } from "../data/i18n";

/*
 * Engagement — "The Promise". A night-rose room: dusky rose paper wall with jali, a cusped arch
 * opening onto the night, a paper moon and a small red planet swinging on threads (Moon n Mars),
 * string lights. The couple glide in, turn toward each other and exchange rings.
 */

const SVG: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <svg
    width={1080}
    height={1920}
    viewBox="0 0 1080 1920"
    style={{ position: "absolute", inset: 0, overflow: "visible" }}
  >
    {children}
  </svg>
);

const FEET = 1470;
const FIG = 640;
const R_X = 360;
const N_X = 720;
const RING: [number, number] = [556, 1098];

const WALL_TOP = "#8A3448";
const WALL_BOT = "#6A2034";

export const EngagementScene: React.FC<SceneProps> = ({ inv, dur, solo }) => {
  const frame = useCurrentFrame();
  const k = solo ? 1.6 : 1; // stretch the action when the scene is the only event
  const T = (f: number) => f * k;
  const ev = inv.events.engagement;

  const cam = useCamera(
    solo
      ? [
          { frame: 0, scale: 1 },
          { frame: T(40), scale: 1.0 },
          { frame: T(150), scale: 1.07, y: 34 },
          { frame: dur - 20, scale: 1.09, y: 40 },
        ]
      : [
          { frame: 0, scale: 1 },
          { frame: T(40), scale: 1 },
          { frame: T(175), scale: 1.045, y: 24 },
        ],
  );

  // staging
  const arch = prog(frame, 0, T(30), EASE.cine);
  const lights = prog(frame, T(6), T(40), EASE.inOut);
  const glideR = prog(frame, T(10), T(46), EASE.out);
  const glideN = prog(frame, T(16), T(46), EASE.out);
  const reach = prog(frame, T(56), T(34), EASE.inOut);
  const ringAt = T(92);
  // last detail line lands ~68f after the title starts; keep >=110f of calm hold after it
  const titleAt = Math.min(T(100), dur - 180);

  const bobR = wave(frame, 60) * 3 * (1 - glideR);
  const bobN = wave(frame, 60, 1) * 3 * (1 - glideN);
  const moonT = 0.3 + wave(frame, 150) * 0.004;
  const flash =
    prog(frame, ringAt, 8, EASE.out) *
    (1 - prog(frame, ringAt + 8, 26, EASE.inOut));

  return (
    <Stage background={WALL_BOT}>
      <Camera state={cam}>
        {/* BACKGROUND — rose paper wall, jali */}
        <ParallaxLayer depth={0.15} blurStrength={0}>
          <SVG>
            <SkyGradient
              id="engagement-wall"
              top={WALL_TOP}
              mid="#7C2A3E"
              bottom={WALL_BOT}
            />
            <rect width={1080} height={1920} fill="url(#jali)" opacity={1} />
            <rect
              width={1080}
              height={1920}
              fill="url(#jali)"
              opacity={0.6}
              transform="translate(36 36)"
            />
          </SVG>
          <PaperBackground
            stock="maroon"
            seed="engagement-wall"
            fibres={40}
            textureOnly
          />
        </ParallaxLayer>

        {/* ARCHITECTURE — cusped arch opening onto the night */}
        <ParallaxLayer depth={0.35} blurStrength={0}>
          <SVG>
            <defs>
              <linearGradient id="engagement-night" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0" stopColor="#24101E" />
                <stop offset="0.6" stopColor="#3E1426" />
                <stop offset="1" stopColor="#5A1C30" />
              </linearGradient>
              <linearGradient
                id="engagement-night-us"
                gradientUnits="userSpaceOnUse"
                x1="0"
                y1="340"
                x2="0"
                y2="1470"
              >
                <stop offset="0" stopColor="#24101E" />
                <stop offset="0.6" stopColor="#3E1426" />
                <stop offset="1" stopColor="#5A1C30" />
              </linearGradient>
            </defs>
            <g
              opacity={0.4 + 0.6 * arch}
              transform={`translate(0 ${(1 - arch) * 20})`}
            >
              <ArchNiche
                cx={540}
                w={780}
                spring={780}
                apex={340}
                floor={1470}
                fill="url(#engagement-night)"
                lobes={5}
              />
            </g>
            {/* side pilasters */}
            {[92, 988].map((x) => (
              <g key={x}>
                <rect
                  x={x - 26}
                  y={520}
                  width={52}
                  height={960}
                  fill="#7A2A3C"
                />
                <rect
                  x={x - 26}
                  y={520}
                  width={10}
                  height={960}
                  fill="#000"
                  opacity={0.12}
                />
                <rect
                  x={x - 32}
                  y={512}
                  width={64}
                  height={12}
                  fill="url(#foil-h)"
                />
                <rect
                  x={x - 32}
                  y={1466}
                  width={64}
                  height={12}
                  fill="url(#foil-h)"
                />
                <path
                  d={`M${x} 560 C${x + 14} 640 ${x - 14} 720 ${x} 800 S${x + 14} 960 ${x} 1040 S${x - 14} 1200 ${x} 1280`}
                  fill="none"
                  stroke={palette.goldLight}
                  strokeWidth={1.4}
                  opacity={0.5}
                />
              </g>
            ))}
          </SVG>
        </ParallaxLayer>
        <ParallaxLayer depth={0.4} blurStrength={0}>
          <GoldDust
            count={34}
            seed="engagement-stars"
            area={[200, 360, 680, 700]}
            color={palette.goldPale}
          />
        </ParallaxLayer>

        {/* HANGING — moon on the brass wire, the red planet, paper stars */}
        <ParallaxLayer depth={0.55} blurStrength={0}>
          <SVG>
            <SunOnWire t={moonT} moon drop={190} />
            {/* re-shade the moon crescent with the night behind it (SunOnWire uses a plain dusk disc) */}
            {(() => {
              const [wx, wy] = wirePoint(moonT);
              return (
                <circle
                  cx={wx + 22}
                  cy={wy + 190 - 10}
                  r={52}
                  fill="url(#engagement-night-us)"
                />
              );
            })()}
            <HangingPlanet
              x={782}
              top={0}
              length={560}
              r={40}
              swing={wave(frame, 110, 0.6) * 2.4}
            />
            <HangingStar
              x={640}
              top={0}
              length={420}
              r={16}
              swing={wave(frame, 90, 1.4) * 3}
            />
            <HangingStar
              x={452}
              top={0}
              length={300}
              r={11}
              swing={wave(frame, 100, 2.2) * 3}
            />
            <HangingStar
              x={900}
              top={0}
              length={330}
              r={13}
              swing={wave(frame, 95, 0.2) * 3}
            />
            <HangingStar
              x={196}
              top={0}
              length={640}
              r={12}
              swing={wave(frame, 105, 2.8) * 3}
            />
          </SVG>
        </ParallaxLayer>

        {/* LIGHTS — two strings of warm bulbs across the arch */}
        <ParallaxLayer depth={0.8} blurStrength={0}>
          <SVG>
            <StringLights
              from={[40, 640]}
              to={[1040, 640]}
              sag={70}
              count={17}
              frame={frame}
              on={lights}
              seed={1}
            />
          </SVG>
        </ParallaxLayer>

        {/* STAGE — marble dais, diyas, couple */}
        <ParallaxLayer depth={1}>
          <SVG>
            <rect x={0} y={1470} width={1080} height={450} fill="#4A1222" />
            <rect
              x={0}
              y={1470}
              width={1080}
              height={450}
              fill="url(#paisley)"
              opacity={0.18}
            />
            <path
              d="M120 1452 L960 1452 L1010 1500 L70 1500 Z"
              fill="#E9D8BD"
            />
            <path
              d="M70 1500 L1010 1500 L1010 1516 L70 1516 Z"
              fill="#C9B08A"
            />
            <path
              d="M120 1452 L960 1452"
              stroke={palette.gold}
              strokeWidth={2}
            />
            <rect x={70} y={1498} width={940} height={3} fill={palette.gold} />
            <ellipse
              cx={540}
              cy={1480}
              rx={330}
              ry={22}
              fill={palette.ink}
              opacity={0.12}
            />
            <PetalScatter
              pts={[
                [180, 1478, 20],
                [250, 1486, 110],
                [470, 1490, 60],
                [640, 1484, 160],
                [820, 1480, 30],
                [900, 1490, 120],
                [560, 1476, 80],
              ]}
              colors={[palette.rose, palette.roseLight, "#8E1B2B"]}
              s={1.1}
            />
            {[160, 920].map((x, i) => (
              <g
                key={x}
                transform={`translate(${x - 30} 1420)`}
                opacity={prog(frame, T(20) + i * 6, 16)}
              >
                <Diya size={60} flicker={frame / 10 + i * 2} />
              </g>
            ))}
          </SVG>
          <div
            style={{
              position: "absolute",
              left: mix(-300, R_X, glideR) - FIG * 0.2,
              top: FEET - FIG * 0.956 + bobR,
              opacity: prog(frame, T(10), 12),
            }}
          >
            <Character
              person={people.rishabh}
              outfit={wardrobe.rishabh.engagement}
              height={FIG}
              pose={{
                rShoulder: mix(-7, -30, reach),
                rElbow: mix(6, -60, reach),
                lShoulder: 7,
                lElbow: -8,
                headTilt: mix(0, 5, reach),
              }}
            />
          </div>
          <div
            style={{
              position: "absolute",
              left: mix(1380, N_X, glideN) - FIG * 0.2,
              top: FEET - FIG * 0.956 + bobN,
              opacity: prog(frame, T(16), 12),
            }}
          >
            <Character
              person={people.nandita}
              outfit={wardrobe.nandita.engagement}
              height={FIG}
              pose={{
                lShoulder: mix(7, 30, reach),
                lElbow: mix(-6, 60, reach),
                rShoulder: -8,
                rElbow: mix(10, 30, reach),
                headTilt: mix(0, -5, reach),
              }}
            />
          </div>
          {/* ring moment — a small gold ring and a sparkle burst */}
          <SVG>
            <g opacity={prog(frame, ringAt - 6, 8)}>
              <circle
                cx={RING[0]}
                cy={RING[1] - 3}
                r={6}
                fill="none"
                stroke="url(#foil)"
                strokeWidth={2.6}
              />
              <path
                d={`M${RING[0]} ${RING[1] - 12} l3 3 l-3 3 l-3 -3 Z`}
                fill="#FFF6DE"
              />
            </g>
            {flash > 0 ? (
              <g
                transform={`translate(${RING[0]} ${RING[1] - 6})`}
                opacity={flash}
              >
                <circle r={46 * flash + 10} fill="#FFE9B8" opacity={0.25} />
                {new Array(8).fill(0).map((_, i) => (
                  <path
                    key={i}
                    d={`M0 ${-14 - 40 * flash} L3 -12 L0 -8 L-3 -12 Z`}
                    transform={`rotate(${i * 45 + 22})`}
                    fill={palette.goldPale}
                  />
                ))}
              </g>
            ) : null}
          </SVG>
          <GoldDust
            count={18}
            seed="engagement-ring"
            area={[RING[0] - 90, RING[1] - 110, 180, 150]}
            start={ringAt}
            color="#FFF1CC"
          />
        </ParallaxLayer>

        {/* FOREGROUND — rose garlands framing the top corners, roses at the base */}
        <ParallaxLayer depth={1.35} blurStrength={7}>
          <SVG>
            <g opacity={prog(frame, 0, T(24))}>
              <GarlandSwag
                from={[-40, 150]}
                to={[330, 60]}
                sag={60}
                r={19}
                seed="eng-fg1"
                tones={["rose", "ivory", "rose", "rose"]}
              />
              <GarlandSwag
                from={[760, 50]}
                to={[1120, 170]}
                sag={56}
                r={19}
                seed="eng-fg2"
                tones={["rose", "rose", "ivory"]}
              />
            </g>
            <Leaf x={20} y={1600} rot={-40} s={3.2} color={palette.greenDeep} />
            <Flower x={40} y={1640} r={44} tone="rose" />
            <Flower x={110} y={1690} r={28} tone="ivory" />
            <Leaf x={1000} y={1640} rot={210} s={3} color={palette.greenDeep} />
            <Flower x={1050} y={1600} r={46} tone="rose" />
            <Flower x={990} y={1680} r={26} tone="ivory" />
          </SVG>
        </ParallaxLayer>
        <FallingPetals
          count={18}
          seed="engagement-petals"
          speed={0.7}
          colors={[palette.rose, palette.roseLight, "#8E1B2B", palette.blush]}
          opacity={prog(frame, 0, 20)}
        />
      </Camera>

      <SceneLighting
        warmth={0.3}
        keyX={50}
        keyY={50}
        spots={[
          { x: 51, y: 57, r: 36, color: "#FFC9A0", intensity: 0.32 },
          { x: 32, y: 29, r: 16, color: "#FFF1D6", intensity: 0.22 },
          { x: 51, y: 57, r: 10, color: "#FFE9B8", intensity: 0.4 * flash },
        ]}
        vignette={0.5}
      />

      <AbsoluteFill>
        {frame >= titleAt ? (
          <EventTitle
            start={titleAt}
            kicker="The Promise"
            title={ev.title}
            lines={[whenBi(ev.date, ev.time), bi(ev.venue)]}
            top={1536}
            theme="light"
            titleSize={96}
          />
        ) : null}
      </AbsoluteFill>
      <GoldFrame />
    </Stage>
  );
};
